/* approved assignment wording (presentation only; stored ids unchanged) */
const GROUP_WORDING = { "CS can assign": "Can receive CS assignments — employer language", "CS priority": "Priority for CS assignments — employer language" };
const ENGINE_GROUPS = ["CS", "Interpreter", "Onboarding 1", "Onboarding 2", "Post-Hire Interpreter"];
const ENGINE_WORDING = { Manual: "Can be assigned manually", "Round Robin": "Include in automatic assignment (round robin)" };
const OPTION_GROUP_RE = /filter options|date preset options|date range options|branches|can assign|priority|worker types|nationalities|Branch check-in operations and filter|Report branch scope|Sign-off eligibility|employer language|Listing filters|Profile status/i;
const FIXED_FEATURES = {
    "worker.details_view": ["Record permissions", "Worker Details", "Open Worker Details"],
    "worker.profile": ["Record permissions", "Worker Details", "View Profile section"],
    "worker.contact_view": ["Contact and communication", "Contact details", "View"],
    "worker.contact_edit": ["Contact and communication", "Contact details", "Edit"],
    "employer.contact_view": ["Record actions", "Contact details", "View"],
    "employer.contact_edit": ["Record actions", "Contact details", "Edit"],
};
const OPTION_PREFIXES = [["worker.filter_profile_", "Profile status"], ["worker.filter_type_", "Worker type"], ["worker.filter_nationality_", "Nationality"]];

/** `fill("Requires {{list}}.", { list })` — the shared translation helper has no interpolation */
export const fill = (text, vars = {}) => Object.entries(vars).reduce((s, [k, v]) => s.split(`{{${k}}}`).join(String(v ?? "")), String(text || ""));
export const t = (key, vars) => (vars ? fill(translation(key), vars) : translation(key));

/* U-0121: the catalogue's English is the structural key; the screen shows the locale's wording through `labels` (one key per
   distinct string, docs/migration/tools/perm_labels_i18n.py) and falls back to the English when a locale has no entry */
export const tx = (text) => {
    const key = catalogue.labels?.[text];
    if (!key) return text;
    const value = translation(key);
    return value === key ? text : value;
};
export const groupLabel = (g) => tx(GROUP_WORDING[g] || g);
export const featureLabel = (name, row) => {
    if (!row || row.module !== PERM_ASSIGNMENT_MODULE) return tx(name);
    if (GROUP_WORDING[name]) return tx(GROUP_WORDING[name]);
    return tx(ENGINE_GROUPS.includes(row.group) && ENGINE_WORDING[name] ? ENGINE_WORDING[name] : name);
};
/** Specification grouping of one row: { group, feature, action, option } (port of the preview's featureFor) */
export const featureFor = (row) => {
    if (row.dyn) return { group: row.group, feature: row.dynFeature || row.group, action: row.label, option: true };
    const fixed = FIXED_FEATURES[row.id];
    if (fixed) return { group: fixed[0], feature: fixed[1], action: fixed[2], option: false };
    const prefixed = OPTION_PREFIXES.find(([prefix]) => row.id.startsWith(prefix));
    if (prefixed) return { group: row.group, feature: prefixed[1], action: row.label, option: true };
    if (row.label.includes(" — ")) {
        const [feature, ...rest] = row.label.split(" — ");
        return { group: row.group, feature, action: rest.join(" — "), option: false };
    }
    if (row.type !== "level" && OPTION_GROUP_RE.test(row.group)) return { group: row.group, feature: row.group, action: row.label, option: true };
    return { group: row.group, feature: row.label, action: "", option: false };
};
export const groupTitle = (g, section = PERM_CONTEXT.SINGLE) => (g === "Access" && section === PERM_CONTEXT.SINGLE ? t(PERM_COPY_KEYS.moduleAccess) : groupLabel(g));
export const sectionTitle = (section, moduleId) => {
    if (section === PERM_CONTEXT.SINGLE) return t(PERM_COPY_KEYS.general);
    if (section === PERM_CONTEXT.NON_OWNER) {
        if (moduleId === "worker") return t(PERM_COPY_KEYS.nonOwnerWorker);
        if (moduleId === "insurance" || moduleId === "invoice") return t(PERM_COPY_KEYS.nonOwnerRecord);
        return t(PERM_COPY_KEYS.nonOwnerCs);
    }
    if (section === PERM_CONTEXT.PARTNER) return t(PERM_COPY_KEYS.assignedWorker);
    return t(PERM_COPY_KEYS.whenPersonIs, { context: tx(catalogue.contextNames[section]) });
};
export const sectionShort = (section) => t(PERM_SECTION_SHORT_KEYS[section] || PERM_COPY_KEYS.shortGeneral);
export const moduleOf = (id) => catalogue.modules.find((m) => m.id === id);
export const moduleName = (id) => tx(moduleOf(id)?.name || id);
export const visibleModules = (audience) => catalogue.modules.filter((m) => m.audiences.includes(audience));
/** binding of a row × context for an audience (partner-specific entries win) */
export const bindingFor = (rowId, context, audience) => (
    (audience === PERM_AUDIENCE.PARTNER && catalogue.bindings[`${rowId}|${context}|partner`]) || catalogue.bindings[`${rowId}|${context}`] || null
);
export const profilesFor = (audience) => catalogue.profiles.filter((p) => p.audience === audience);
export const profileLabel = (profile) => (PERM_PROFILE_LABEL_KEYS[profile.id] ? t(PERM_PROFILE_LABEL_KEYS[profile.id]) : profile.name);
export const listText = (names) => (names.length < 2 ? names[0] || "" : `${names.slice(0, -1).join(", ")} and ${names[names.length - 1]}`);
export const idSafe = (s) => String(s).replace(/[^a-z0-9]+/gi, "-");
